 }
+
+/** Adds one provider round's usage to the turn total; a round that reported nothing leaves the total as it was. */
+export function addRoundUsage(total: TurnUsage | undefined, round: UsageMetadata | undefined): TurnUsage | undefined {
+  if (!round) return total;
+  if (!total) return round;
+  return {
+    inputTokens: total.inputTokens + round.inputTokens,
+    outputTokens: total.outputTokens + round.outputTokens,
+    totalTokens: total.totalTokens + round.totalTokens,
+  };
+}
